146	// sendInvite emails the invite's link to the invited address.
147	func (s *Server) sendInvite(ctx context.Context, inv store.Invite) error {
148		o, _ := s.store.Org(inv.OrgID)
149		link := s.baseURL + "/invites/accept?token=" + url.QueryEscape(inv.Token)
150		return s.mail.Send(ctx, mail.Message{
151			To:      inv.Email,
152			Subject: fmt.Sprintf("You are invited to join %s on Tally", o.Name),
153			Body:    fmt.Sprintf("You have been invited to join %s on Tally as %s.\n\nAccept the invitation: %s\n", o.Name, inv.Role, link),
154		})
155	}
