157	func (s *Server) revokeInvite(w http.ResponseWriter, r *http.Request, p auth.Principal) {
158		if !auth.CanManageTeam(p.Role) {
159			writeError(w, http.StatusForbidden, "forbidden", "only owners and admins manage invites")
160			return
161		}
162		if _, err := s.store.RevokeInvite(p.OrgID, r.PathValue("id"), s.clock.Now()); err != nil {
163			s.storeError(w, err)
164			return
165		}
166		w.WriteHeader(http.StatusNoContent)
167	}
