169	// acceptInvite needs no API key: the invite's token is the credential. It answers the new member and their first API key.
170	func (s *Server) acceptInvite(w http.ResponseWriter, r *http.Request) {
171		var in struct {
172			Token string `json:"token"`
173			Name  string `json:"name"`
174		}
175		if !decode(w, r, &in) {
176			return
177		}
178		u, m, k, err := s.store.AcceptInvite(in.Token, in.Name, s.clock.Now())
179		if err != nil {
