181				writeError(w, http.StatusNotFound, "invite_not_found", "no such invite")
182				return
183			}
184			s.storeError(w, err)
185			return
186		}
187		writeJSON(w, http.StatusCreated, map[string]any{"user": u, "member": s.memberView(m), "api_key": k})
188	}
