	for id, old := range s.invites {
		if old.OrgID == orgID && normEmail(old.Email) == normEmail(email) && old.AcceptedAt == nil && old.RevokedAt == nil {
			old.RevokedAt = &t
			s.invites[id] = old
		}
	}
	token, hash := newInviteToken()
	inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, TokenHash: hash, InvitedBy: invitedBy, CreatedAt: t, ExpiresAt: t.Add(InviteLifetime)}
	s.invites[inv.ID] = inv
	inv.Token = token
	return inv, nil
}

